mapper.select:
/* agent_runtime_authorization_current */ WITH runtime_tenant AS MATERIALIZED ( SELECT #{tenant}::text AS tenant_id WHERE COALESCE(current_setting('app.tenant_id',true),'')=#{tenant} ) SELECT authorization_current.authentication_ref, authorization_current.tenant_id, authorization_current.principal_kind, authorization_current.principal_id, authorization_current.integration_id, authorization_current.credential_version, authorization_current.target_kind, authorization_current.target_id, authorization_current.session_id, authorization_current.end_user_id, authorization_current.channel, authorization_current.source, authorization_current.expires_at, authorization_current.active, authorization_current.identity_snapshot, authorization_current.current_time, authorization_current.current_service_status, authorization_current.current_service_integration_id, authorization_current.current_service_credential_version, authorization_current.current_service_scopes, authorization_current.owner_available, authorization_current.session_scope_allowed FROM runtime_tenant CROSS JOIN LATERAL ( SELECT a.authentication_ref, a.tenant_id, a.principal_kind, a.principal_id, a.integration_id, a.credential_version, a.agent_id, a.session_id, a.end_user_id, a.channel, a.source, a.expires_at, a.active, a.recorded_at, a.target_kind, a.target_id, v.identity_snapshot, clock_timestamp() AS current_time, sp.status AS current_service_status, sp.integration_id AS current_service_integration_id, sp.credential_version AS current_service_credential_version, COALESCE((SELECT string_agg( replace(encode(convert_to(value, 'UTF8'), 'base64'), E'\n', ''), '.' ORDER BY value) FROM jsonb_array_elements_text(sp.scopes) AS service_scope(value)), '') AS current_service_scopes,
(a.target_kind='GROUP' AND a.end_user_id IS NULL AND
)
(((((a.target_kind = 'AGENT' AND EXISTS(SELECT 1 FROM public.nw_agents WHERE tenant_id::text = a.tenant_id AND id::text = a.target_id AND status = 'published')) OR (a.target_kind = 'TEAM' AND EXISTS(SELECT 1 FROM public.nw_agent_teams t JOIN public.nw_agent_team_versions v ON v.tenant_id = t.tenant_id AND v.team_id = t.id AND v.revision = t.published_revision WHERE t.tenant_id::text = a.tenant_id AND t.id = a.target_id AND t.status = 'published'))) AND EXISTS(SELECT 1 FROM public.nw_end_users WHERE tenant_id::text = a.tenant_id AND id::text = CAST(a.end_user_id AS text) AND status = 'active')) OR EXISTS(SELECT 1 FROM public.nw_runtime_host_owners h WHERE a.target_kind = 'AGENT' AND h.tenant_id=a.tenant_id AND h.agent_id=a.target_id AND h.session_id=a.session_id AND h.end_user_id=a.end_user_id AND (a.principal_kind='SYSTEM' OR h.integration_id=a.integration_id))) AND NOT EXISTS(SELECT 1 FROM public.agent_runtime_session_owners WHERE tenant_id = a.tenant_id AND target_kind = a.target_kind AND target_id = a.target_id AND session_id = a.session_id AND end_user_id IS DISTINCT FROM a.end_user_id) AND
)
AS owner_available, NOT EXISTS(SELECT 1 FROM public.agent_runtime_sessions WHERE tenant_id = a.tenant_id AND target_kind = a.target_kind AND target_id = a.target_id AND session_id = a.session_id AND (end_user_id IS DISTINCT FROM a.end_user_id OR (a.principal_kind = 'SERVICE' AND scope_key != 'open-platform:' || a.integration_id))) AS session_scope_allowed FROM public.nw_runtime_identity_verifications v JOIN public.nw_runtime_authentication_facts a ON a.tenant_id = v.tenant_id AND a.authentication_ref = v.authentication_ref LEFT JOIN public.nw_service_principals sp ON a.principal_kind = 'SERVICE' AND sp.tenant_id::text = a.tenant_id AND sp.principal_id = a.principal_id WHERE v.tenant_id = runtime_tenant.tenant_id AND v.verification_ref = #{reference} AND a.target_kind = #{targetKind} OFFSET 0 ) authorization_current

SELECT EXISTS(SELECT 1 FROM public.nw_service_principals
  WHERE tenant_id::text = #{tenantId} AND principal_id = #{principalId}
    AND integration_id = #{integrationId} AND credential_version = #{credentialVersion} AND status = 'active')

SELECT jsonb_array_elements_text(scopes) FROM public.nw_service_principals
  WHERE tenant_id::text = #{tenantId} AND principal_id = #{principalId}
    AND integration_id = #{integrationId} AND credential_version = #{credentialVersion} AND status = 'active'

SELECT ((#{fact.targetKind}<>'GROUP' AND NOT EXISTS (SELECT 1 FROM public.nw_runtime_agent_run_bindings WHERE tenant_id=#{fact.tenantId} AND run_id=#{runId}) AND NOT EXISTS(SELECT 1 FROM public.nw_agent_deployments deployment WHERE deployment.tenant_id::text=#{fact.tenantId} AND deployment.agent_id::text=#{agentId})) OR EXISTS (SELECT 1 FROM public.nw_runtime_agent_run_bindings binding WHERE binding.tenant_id=#{fact.tenantId} AND binding.run_id=#{runId} AND binding.session_id=#{fact.sessionId} AND binding.target_kind=#{fact.targetKind} AND binding.target_id=#{fact.targetId} AND binding.end_user_id IS NOT DISTINCT FROM #{fact.endUserId,jdbcType=BIGINT} AND binding.actor_agent_id=#{agentId}
AND EXISTS( SELECT 1 FROM public.nw_group_bindings g JOIN public.nw_group_service_agents service ON service.tenant_id=g.tenant_id AND service.integration_id=g.integration_id AND service.group_binding_id=g.id AND service.agent_id::text=#{agentId} AND service.status='active' JOIN public.nw_agents actual ON actual.tenant_id=service.tenant_id AND actual.id=service.agent_id AND actual.status='published' JOIN public.nw_group_memberships original_requester ON original_requester.tenant_id=g.tenant_id AND original_requester.integration_id=g.integration_id AND original_requester.group_binding_id=g.id AND original_requester.end_user_id=binding.requester_end_user_id AND original_requester.status='active' JOIN public.nw_end_users requester_user ON requester_user.tenant_id=original_requester.tenant_id AND requester_user.id=original_requester.end_user_id AND requester_user.external_integration_id=g.integration_id AND requester_user.status='active' JOIN public.nw_group_front_slots slot ON slot.tenant_id=g.tenant_id AND slot.integration_id=g.integration_id AND slot.group_binding_id=g.id WHERE g.tenant_id::text=binding.tenant_id AND g.id::text=binding.target_id AND g.status='active' AND (#{fact.principalKind}='SYSTEM' OR g.integration_id=#{fact.integrationId}) AND slot.active_run_id=binding.scope_snapshot->'primary_run'->>'run_id' AND NOT EXISTS(SELECT 1 FROM public.nw_agent_deployments fixed WHERE fixed.tenant_id=g.tenant_id AND fixed.agent_id=actual.id AND fixed.integration_id IS NOT NULL AND fixed.integration_id<>g.integration_id) AND ((#{fact.source} NOT LIKE 'group-respond:%' AND #{fact.source} NOT LIKE 'group-control:%') OR EXISTS( SELECT 1 FROM public.nw_group_memberships responder JOIN public.nw_end_users responder_user ON responder_user.tenant_id=responder.tenant_id AND responder_user.id=responder.end_user_id AND responder_user.status='active' AND responder_user.external_integration_id=responder.integration_id WHERE responder.tenant_id=g.tenant_id AND responder.integration_id=g.integration_id AND responder.group_binding_id=g.id AND responder.status='active' AND responder.end_user_id::text=substring(#{fact.source} from 15) AND (responder.role='manager' OR responder.end_user_id=binding.requester_end_user_id))))
AND NOT EXISTS(SELECT 1 FROM public.nw_integration_run_sources source LEFT JOIN public.nw_tenants institution ON institution.id=source.tenant_id LEFT JOIN public.nw_institution_integrations integration ON integration.tenant_id=source.tenant_id AND integration.integration_id=source.integration_id LEFT JOIN public.nw_integration_business_scopes business_scope ON business_scope.tenant_id=source.tenant_id AND business_scope.integration_id=source.integration_id AND business_scope.scope_id=source.business_scope_id WHERE source.tenant_id::text=#{fact.tenantId} AND source.run_id=#{runId} AND (institution.status IS NULL OR institution.status NOT IN ('active','warning') OR (source.integration_id IS NOT NULL AND integration.integration_id IS NULL) OR (source.business_scope_id IS NOT NULL AND business_scope.status IS DISTINCT FROM 'active'))) AND ( (NOT COALESCE(jsonb_exists(binding.scope_snapshot->'authorizations',#{agentId}),false) AND NOT EXISTS(SELECT 1 FROM public.nw_agent_deployments deployment WHERE deployment.tenant_id::text=#{fact.tenantId} AND deployment.agent_id::text=#{agentId}) AND NOT EXISTS(SELECT 1 FROM public.nw_integration_run_sources source WHERE source.tenant_id::text=#{fact.tenantId} AND source.run_id=#{runId} AND source.grant_id IS NOT NULL)) OR (COALESCE(jsonb_exists(binding.scope_snapshot->'authorizations',#{agentId}),false) AND COALESCE(public.agent_grant_chain_available( binding.scope_snapshot->'authorizations'->#{agentId}->'grant_chain', binding.tenant_id::bigint, (binding.scope_snapshot->'authorizations'->#{agentId}->'grant_chain'->>'definition_id')::bigint, 'execute'),false))))) AND

SELECT NOT EXISTS(SELECT 1 FROM public.agent_runtime_sessions
  WHERE tenant_id = #{tenantId} AND target_kind = #{targetKind}
    AND target_id = #{targetId} AND session_id = #{sessionId}
    AND (end_user_id IS DISTINCT FROM #{endUserId}
      OR (#{principalKind} = 'SERVICE' AND scope_key != 'open-platform:' || #{integrationId})))
